        where (s.user_id = #{uid} or (state in (1,2) and d.dept_id = #{deptId}))
         and xueyuan = #{xueyuan}
         and mingcheng like concat('%', #{mingcheng}, '%')
         and huopishijain = #{huopishijain}
         and fenlei = #{fenlei}
         and YEAR(DATE_ADD(createtime,INTERVAL 1 MONTH)) = #{year}
        order by
        case
--         待教研室审核
        when state = 1 then 1
--         教研室通过
        when state in (2) then 2

        when state  = 0 then 3
        end,
        createtime desc


        where  s.user_id = #{uid} or state in (4,6)
        and  d.dept_name like concat('%', #{jiaoyanshi}, '%')
        and  u.user_name like concat('%', #{xingming}, '%')
         and xueyuan = #{xueyuan}
         and mingcheng like concat('%', #{mingcheng}, '%')
         and huopishijain = #{huopishijain}
         and fenlei = #{fenlei}
         and YEAR(DATE_ADD(createtime,INTERVAL 1 MONTH)) = #{year}
         and user_name like concat('%', #{userName}, '%')
        ${params.dataScope}
        order by
        case
--         待科研处审核
        when state = 4 then 1
--         科研处通过
        when state in (6) then 2

        when state  = 0 then 3
        end,
         createtime desc

